import numpy as np
import seaborn as sns

def task_func(P, T):
    if not isinstance(P, np.ndarray) or not isinstance(T, np.ndarray):
        raise TypeError("P and T must be numpy arrays or matrices.")
    if P.ndim != 2:
        raise ValueError("P must be a 2D matrix.")
    if T.ndim != 3:
        raise ValueError("T must be a 3D tensor.")
    if P.shape[1] != T.shape[0]:
        raise ValueError("The number of columns in P must match the first dimension of T.")

    result = np.einsum("ij,jkl->ikl", np.asarray(P), np.asarray(T))
    result_2d = result.reshape(result.shape[0], -1)
    ax = sns.heatmap(result_2d)

    return result, ax
